constraint.cypher:
UNWIND [x IN split($requiredDependencies, ',') | trim(x)] AS req
    WITH req WHERE req <> '' AND NOT EXISTS { MATCH (:Maven:Pom)-[:DECLARES_DEPENDENCY]->(:Maven:Dependency)-[:TO_ARTIFACT]->(a:Maven:Artifact) WHERE (a.group + ':' + a.name) CONTAINS req }
    RETURN req AS Element, req AS Fqn, 'required dependency is not declared' AS Detail

MATCH (pom:Maven:Pom)-[:USES_PLUGIN]->(p:Maven:Plugin)-[:IS_ARTIFACT]->(:Maven:Artifact {group: 'org.jacoco', name: 'jacoco-maven-plugin'})
    WHERE NOT EXISTS { MATCH (p)-[:HAS_EXECUTION]->(:Maven:PluginExecution)-[:HAS_GOAL]->(:Maven:ExecutionGoal {name: 'check'}) }
    RETURN DISTINCT p AS Element, pom.fileName AS Fqn, 'jacoco-maven-plugin without check goal' AS Detail

MATCH (pom:Maven:Pom) WITH collect(pom) AS poms
    WHERE size(poms) > 0 AND NOT EXISTS { MATCH (:Maven:Pom)-[:USES_PLUGIN]->(:Maven:Plugin)-[:IS_ARTIFACT]->(:Maven:Artifact {name: 'maven-enforcer-plugin'}) }
    RETURN poms[0] AS Element, poms[0].fileName AS Fqn, 'maven-enforcer-plugin is not used' AS Detail
